function onceDemo(values) {
  let timesRun = 0
  function once(fn) {
    let called = false
    let result
    return function (...args) {
      if (!called) {
        called = true
        result = fn.apply(this, args)
      }
      return result
    }
  }
  const wrapped = once((x) => {
    timesRun++
    return x * 10
  })
  const results = values.map((v) => wrapped(v))
  return { results, timesRun }
}

