solution:
function composeApply(names, x) {
  const library = {
    double: (v) => v * 2,
    inc: (v) => v + 1,
    square: (v) => v * v,
    negate: (v) => -v,
  }
  const compose =
    (...fns) =>
    (input) =>
      fns.reduceRight((acc, fn) => fn(acc), input)
  return compose(...names.map((name) => library[name]))(x)
}

