solution:
function lruCache(capacity, ops) {
  const cache = new Map()
  const results = []
  for (const [op, key, value] of ops) {
    if (op === 'get') {
      if (!cache.has(key)) {
        results.push(-1)
      } else {
        const v = cache.get(key)
        cache.delete(key)
        cache.set(key, v)
        results.push(v)
      }
    } else {
      if (cache.has(key)) cache.delete(key)
      cache.set(key, value)
      if (cache.size > capacity) {
        const oldest = cache.keys().next().value
        cache.delete(oldest)
      }
    }
  }
  return results
}

